 curveVertex ( 10 , 10 ) ; 
 curveVertex ( 15 , 40 ) ; 
 curveVertex ( 40 , 35 ) ; 
 curveVertex ( 25 , 15 ) ; 
 curveVertex ( 15 , 25 ) ; 
 curveVertex ( 10 , 10 ) ; 
 curveVertex ( 15 , 40 ) ; 
 endShape ( ) ;
``` |```
beginShape ( ) ; 

 splineVertex ( 10 , 10 ) ;
splineVertex ( 15 , 40 ) ; 
 splineVertex ( 40 , 35 ) ; 
 splineVertex ( 25 , 15 ) ; 
 splineVertex ( 15 , 25 ) ; 

 endShape ( CLOSE ) ;
``` |

### Async loading (thanks to [@limzykenneth](https://github.com/limzykenneth) )

Rather than having a `preload` function, p5 2.0 has `async setup` !

|1\.x |2\.0 |
| --- | --- |
|```
let img ; 

 function preload ( ) { 
  img = loadImage ( 'cat.jpg' ) ; 
 } 

 function setup ( ) { 
  createCanvas ( 200 , 200 ) ; 
 }
``` |```
let img ; 

 async function setup ( ) { 
  createCanvas ( 200 , 200 ) ; 
  img = await loadImage ( 'cat.jpg' ) ; 
 }
``` |

🚧 Since this is a breaking change from 1.x to 2.0, you can weight in on the compatibility discussion [here](https://github.com/processing/p5.js/issues/7488)

