def norm(s): return re.sub(r'\s+', '', s.strip() if isinstance(s, str) else '')

def calls(name, code):
    out = []
    for m in re.finditer(r'\b' + re.escape(name) + r'\s*\(', code):
        i = m.end(); depth = 1; args = []; cur = []
        while i < len(code) and depth > 0:
            c = code[i]
            if c == '(': depth += 1; cur.append(c)
            elif c == ')':
                depth -= 1
                if depth == 0: break
                cur.append(c)
            elif c == ',' and depth == 1: args.append(''.join(cur)); cur = []
            else: cur.append(c)
            i += 1
        if depth == 0:
            raw = ''.join(cur)
            if raw.strip(): args.append(raw)
            out.append([a.strip() for a in args])
    return out

errors = 0
for f in sorted(glob.glob('src/data/courses/*.yaml')):
    with open(f) as fh: data = yaml.safe_load(fh)
    for ex in data.get('exercises', []):
        sol = ex.get('solution'); tasks = ex.get('tasks', [])
        for ti, task in enumerate(tasks):
            is_final = ti == len(tasks) - 1
            tsol = task.get('solution') or (sol if is_final else None)
            if tsol is None: continue
            for rule in task.get('validation', []):
                if rule['type'] == 'functionCall':
                    name = rule['name']; cs = calls(name, tsol)
                    if len(cs) == 0:
                        print(f"ERR {f} {ex['id']}/{task['id']}: solution missing {name}()"); errors += 1; continue
                    if 'exactArgs' in rule and not any(len(c) == rule['exactArgs'] for c in cs):
                        print(f"ERR {f} {ex['id']}/{task['id']}: {name}() args {[len(c) for c in cs]} != {rule['exactArgs']}"); errors += 1
                    if 'minArgs' in rule and not any(len(c) >= rule['minArgs'] for c in cs):
                        print(f"ERR {f} {ex['id']}/{task['id']}: {name}() args {[len(c) for c in cs]} < {rule['minArgs']}"); errors += 1
            if is_final and task.get('solution') and sol:
                if norm(task['solution']) != norm(sol):
                    print(f"ERR {f} {ex['id']}: final task solution != exercise solution"); errors += 1
print("done", errors, "error(s)")
