    names = set()
    for m in re.finditer(r'function\s+([A-Za-z_$][\w$]*)', code): names.add(m.group(1))
    for m in re.finditer(r'\b(?:let|const|var)\s+([A-Za-z_$][\w$]*)', code): names.add(m.group(1))
    for m in re.finditer(r'function\s*\(([^)]*)\)', code):
        for p in m.group(1).split(','):
            p = p.strip()
            if p and re.match(r'^[A-Za-z_$][\w$]*$', p): names.add(p)
    return names

errs = 0
callRE = re.compile(r'(?<![\w$.])\b([A-Za-z_$][\w$]*)\s*\(')
for f in sorted(glob.glob('src/data/courses/*.yaml')):
    data = yaml.safe_load(open(f))
    for ex in data.get('exercises', []):
        blocks = [("startingCode", ex.get('startingCode')), ("solution", ex.get('solution'))]
        for t in ex.get('tasks', []):
            blocks.append((f"task.{t['id']}.solution", t.get('solution')))
        for label, src in blocks:
            if not src: continue
            code = strip(src); dcl = declared(code)
            for m in callRE.finditer(code):
                name = m.group(1)
                if name not in known and name not in dcl:
                    print(f"ERR {f} {ex['id']} {label}: unknown call {name}()"); errs += 1
            for m in re.finditer(r'\.([A-Za-z_$][\w$]*)\b', code):
                name = m.group(1)
                if name not in known and name not in MEM and name not in dcl:
                    print(f"ERR {f} {ex['id']} {label}: unknown member .{name}"); errs += 1
            for m in re.finditer(r'\b([A-Z][A-Z0-9_]*)\b', code):
                name = m.group(1)
                if name not in CONSTS and name not in JSG:
                    print(f"ERR {f} {ex['id']} {label}: unknown constant {name}"); errs += 1
print("done", errs, "error(s)")
